mapper.select:
SELECT COUNT(*) = 0 FROM appointments a
INNER JOIN appointment_resources ar ON a.id = ar.appointment_id
WHERE ar.resource_id = #{resourceId}
AND a.appointment_date = #{date}
AND a.status NOT IN ('CANCELLED', 'NO_SHOW')
AND (
    (#{startTime} >= a.appointment_time AND #{startTime} < ADDTIME(a.appointment_time, SEC_TO_TIME(a.duration * 60))) OR
    (#{endTime} > a.appointment_time AND #{endTime} <= ADDTIME(a.appointment_time, SEC_TO_TIME(a.duration * 60))) OR
    (#{startTime} <= a.appointment_time AND #{endTime} >= ADDTIME(a.appointment_time, SEC_TO_TIME(a.duration * 60)))
)

mapper.insert:
INSERT INTO resource (
    tenant_id, name, type, description, capacity, location,
    equipment, specialties, hourly_rate, status, phone, country_code, email, position, start_date, avatar, icon, created_at, updated_at
) VALUES (
    #{tenantId}, #{name}, #{type}, #{description}, #{capacity}, #{location},
    #{equipment}, #{specialties}, #{hourlyRate}, #{status}, #{phone}, #{countryCode}, #{email}, #{position}, #{startDate}, #{avatar}, #{icon}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT * FROM resource_availability 
WHERE resource_id = #{resourceId}
ORDER BY day_of_week, start_time

mapper.insert:
INSERT INTO resource_availability (
    resource_id, day_of_week, start_time, end_time, is_available, segment_order, created_at, updated_at
) VALUES (
    #{resourceId}, #{dayOfWeek}, #{startTime}, #{endTime}, #{isAvailable}, #{segmentOrder}, #{createdAt}, #{updatedAt}
)

INSERT INTO resource_booking_slots (
    resource_id, appointment_id, booking_date, start_time, end_time, status, created_at, updated_at
) VALUES (
    #{resourceId}, #{appointmentId}, #{bookingDate}, #{startTime}, #{endTime}, #{status}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT COUNT(*) > 0 FROM resource_booking_slots
WHERE resource_id = #{resourceId}
AND booking_date = #{bookingDate}
AND status = 'BOOKED'
AND (
    (#{startTime} >= start_time AND #{startTime} < end_time) OR
    (#{endTime} > start_time AND #{endTime} <= end_time) OR
    (#{startTime} <= start_time AND #{endTime} >= end_time)
)

SELECT COUNT(*) > 0 FROM resource_booking_slots
WHERE resource_id = #{resourceId}
AND booking_date = #{bookingDate}
AND status = 'BOOKED'
AND appointment_id != #{excludeAppointmentId}
AND (
    (#{startTime} >= start_time AND #{startTime} < end_time) OR
    (#{endTime} > start_time AND #{endTime} <= end_time) OR
    (#{startTime} <= start_time AND #{endTime} >= end_time)
)

SELECT id, resource_id, day_of_week, start_time, end_time, is_available, segment_order, created_at, updated_at
FROM resource_availability
WHERE resource_id = #{resourceId}
AND day_of_week = #{dayOfWeek}
ORDER BY segment_order

mapper.delete:
DELETE FROM resource_availability
WHERE resource_id = #{resourceId}
AND day_of_week = #{dayOfWeek}
